<script setup>
import { computed, onMounted, reactive, ref, watch } from "vue";
import axios from "axios";
import Swal from "sweetalert2";
import AttendanceRiskBadge from "./AttendanceRiskBadge.vue";
import { waitForAndDownloadAttendanceExport } from "../../utils/attendance-export";

const props = defineProps({ filters: { type: Object, required: true }, catalogs: { type: Object, default: () => ({}) }, capabilities: { type: Object, default: () => ({}) }, configuration: { type: Object, default: () => ({}) }, initialPattern: { type: String, default: "" } });
const rows = ref([]); const meta = ref({}); const loading = ref(false); const error = ref(""); const detail = ref(null); const detailLoading = ref(false); const creating = ref(false);
const local = reactive({ search: "", risk_level: "", pattern_type: props.initialPattern, course_section_id: props.filters.course_section_id || "", sort: "priority", direction: "desc", page: 1, per_page: 25 });
const caseForm = reactive({ initial_situation: "", priority: "preventive", responsible_user_id: "", reference_adult_user_id: "", next_review_on: "", reason: "Apertura de expediente para acompañamiento preventivo." });
let searchTimer;
const query = computed(() => ({ ...props.filters, ...Object.fromEntries(Object.entries(local).filter(([, value]) => value !== "" && value !== null)) }));
const pct = (value) => value === null || value === undefined ? "Sin datos" : `${Number(value).toLocaleString("es-CL", { maximumFractionDigits: 1 })}%`;
const date = (value) => value ? new Date(`${String(value).slice(0,10)}T12:00:00`).toLocaleDateString("es-CL") : "—";
const load = async () => { loading.value = true; error.value = ""; try { const { data } = await axios.get("/api/attendance-management/students", { params: query.value }); rows.value = data.data || []; meta.value = data.meta || {}; } catch (requestError) { error.value = requestError.response?.data?.message || "No fue posible cargar estudiantes."; } finally { loading.value = false; } };
const openStudent = async (id) => { detailLoading.value = true; detail.value = { student: { id } }; try { const { data } = await axios.get(`/api/attendance-management/students/${id}`, { params: props.filters }); detail.value = data; caseForm.initial_situation = `Se abre expediente a partir del análisis de asistencia: ${data.risk?.explanations?.[0] || 'requiere revisión preventiva'}.`; caseForm.priority = ["critical", "red"].includes(data.risk?.level) ? "critical" : data.risk?.level === "orange" ? "high" : "preventive"; } catch (requestError) { detail.value = null; await Swal.fire({ icon: "error", title: "No se pudo abrir la ficha", text: requestError.response?.data?.message || "Intenta nuevamente." }); } finally { detailLoading.value = false; } };
const closeDetail = () => { detail.value = null; creating.value = false; };
const createCase = async () => { if (!detail.value?.student?.id) return; try { const payload = { student_profile_id: detail.value.student.id, academic_year_id: Number(props.filters.academic_year_id), course_section_id: detail.value.records?.slice(-1)?.[0]?.course_section_id || null, initial_situation: caseForm.initial_situation, priority: caseForm.priority, responsible_user_id: caseForm.responsible_user_id || null, reference_adult_user_id: caseForm.reference_adult_user_id || null, next_review_on: caseForm.next_review_on || null, reason: caseForm.reason }; const { data } = await axios.post("/api/attendance-management/cases", payload); detail.value.cases = [data, ...(detail.value.cases || [])]; creating.value = false; await Swal.fire({ icon: "success", title: `Expediente ${data.folio} creado`, timer: 1700, showConfirmButton: false }); } catch (requestError) { await Swal.fire({ icon: "error", title: "No se pudo crear el expediente", text: Object.values(requestError.response?.data?.errors || {})[0]?.[0] || requestError.response?.data?.message || "Revisa los datos." }); } };
const exportStudent = async (reportType) => { let progress = false; try { const response = await axios.post("/api/attendance-statistics/exports", { academic_year_id: Number(props.filters.academic_year_id), report_type: reportType, format: "pdf", filters: { ...props.filters, student_profile_id: detail.value.student.id } }); Swal.fire({ title: "Preparando PDF", text: reportType === "family_interview" ? "Creando una versión apta para entrevista familiar." : "Creando la ficha individual autorizada.", allowOutsideClick: false, didOpen: () => Swal.showLoading() }); progress = true; await waitForAndDownloadAttendanceExport(response.data); Swal.close(); } catch (requestError) { if (progress) Swal.close(); await Swal.fire({ icon: "error", title: "No se pudo generar el PDF", text: requestError.response?.data?.message || requestError.message }); } };
const changeSort = (sort) => { if (local.sort === sort) local.direction = local.direction === "asc" ? "desc" : "asc"; else { local.sort = sort; local.direction = sort === "attendance" ? "asc" : "desc"; } load(); };
const goPage = (page) => { local.page = page; load(); };
const scheduleSearch = () => { clearTimeout(searchTimer); searchTimer = setTimeout(() => { local.page = 1; load(); }, 350); };
watch(() => [props.filters.academic_year_id, props.filters.course_section_id], () => { local.course_section_id = props.filters.course_section_id || ""; local.page = 1; load(); });
watch(() => props.initialPattern, (value) => { local.pattern_type = value || ""; load(); });
onMounted(load);
defineExpose({ openStudent, reload: load });
</script>

<template>
  <section class="students-workspace">
    <div class="filter-bar">
      <label class="search"><i class="bx bx-search"></i><input v-model="local.search" type="search" placeholder="Buscar por estudiante o RUT" @input="scheduleSearch"></label>
      <label><span>Curso</span><select v-model="local.course_section_id" @change="local.page=1;load()"><option value="">Todos los autorizados</option><option v-for="course in catalogs.courses || []" :key="course.id" :value="course.id">{{ course.display_name }}</option></select></label>
      <label><span>Nivel de atención</span><select v-model="local.risk_level" @change="local.page=1;load()"><option value="">Todos</option><option v-for="risk in catalogs.risk_levels || []" :key="risk.value" :value="risk.value">{{ risk.label }}</option></select></label>
      <label><span>Patrón</span><select v-model="local.pattern_type" @change="local.page=1;load()"><option value="">Todos los patrones</option><option value="monday_absence">Ausencias los lunes</option><option value="friday_absence">Ausencias los viernes</option><option value="consecutive_absences">Ausencias consecutivas</option><option value="attendance_drop">Deterioro reciente</option><option value="intermittent_absence">Ausencias intermitentes</option><option value="holiday_adjacent_absence">Antes/después de feriados</option><option value="frequent_lateness">Atrasos frecuentes</option><option value="early_departure">Retiros anticipados</option><option value="unjustified_absence">Ausencias injustificadas</option></select></label>
      <button type="button" class="btn btn-light" @click="Object.assign(local,{search:'',risk_level:'',pattern_type:'',course_section_id:props.filters.course_section_id||'',page:1});load()"><i class="bx bx-reset"></i>Limpiar</button>
    </div>

    <div class="table-panel">
      <div v-if="error" class="state error"><i class="bx bx-error-circle"></i>{{ error }}<button type="button" @click="load">Reintentar</button></div>
      <div v-else-if="loading && !rows.length" class="state"><span class="spinner-border spinner-border-sm"></span>Cargando priorización…</div>
      <div v-else class="table-responsive">
        <table class="table align-middle mb-0">
          <thead><tr><th><button type="button" @click="changeSort('student_name')">Estudiante</button></th><th>Curso</th><th><button type="button" @click="changeSort('attendance')">Asistencia</button></th><th>Últimos 30 días</th><th><button type="button" @click="changeSort('lost_days')">Días perdidos</button></th><th>Señales</th><th>Nivel</th><th></th></tr></thead>
          <tbody><tr v-for="student in rows" :key="student.student_id"><td><button type="button" class="student-link" @click="openStudent(student.student_id)"><strong>{{ student.name }}</strong><span>{{ student.rut || 'Sin RUT' }}</span></button></td><td><strong class="course-name">{{ student.course || 'Sin curso' }}</strong><span class="muted">{{ student.level }}</span></td><td><strong :class="{ danger: Number(student.attendance_rate) < 85 }">{{ pct(student.attendance_rate) }}</strong><span class="trend" :class="student.trend"><i class="bx" :class="student.trend==='improving'?'bx-trending-up':student.trend==='declining'?'bx-trending-down':'bx-minus'"></i>{{ student.trend_points === null ? 'Sin comparación' : `${Number(student.trend_points)>0?'+':''}${student.trend_points} pts` }}</span></td><td>{{ pct(student.attendance_last_30_days) }}</td><td><strong>{{ student.lost_days }}</strong><span class="muted">{{ student.unjustified_absences }} sin justificar</span></td><td><span class="signal"><i class="bx bx-pulse"></i>{{ student.active_patterns_count }} patrones</span><span v-if="student.consecutive_absences" class="signal critical">{{ student.consecutive_absences }} consecutivas</span></td><td><AttendanceRiskBadge :level="student.risk_level" :label="student.risk_label" compact /></td><td><button type="button" class="open-button" aria-label="Abrir ficha" @click="openStudent(student.student_id)"><i class="bx bx-right-arrow-alt"></i></button></td></tr><tr v-if="!rows.length"><td colspan="8"><div class="state"><i class="bx bx-check-shield"></i>No hay estudiantes para los filtros seleccionados.</div></td></tr></tbody>
        </table>
      </div>
      <footer class="pagination-bar"><span>{{ meta.total || 0 }} estudiantes</span><div><button type="button" :disabled="meta.current_page<=1" @click="goPage(meta.current_page-1)"><i class="bx bx-chevron-left"></i></button><span>Página {{ meta.current_page || 1 }} de {{ meta.last_page || 1 }}</span><button type="button" :disabled="meta.current_page>=meta.last_page" @click="goPage(meta.current_page+1)"><i class="bx bx-chevron-right"></i></button></div></footer>
    </div>

    <div v-if="detail" class="drawer-backdrop" @click.self="closeDetail">
      <aside class="student-drawer" aria-label="Ficha integral del estudiante">
        <header><div><span class="eyebrow">FICHA DE ASISTENCIA</span><h2>{{ detail.student?.name || 'Cargando estudiante…' }}</h2><p>{{ detail.student?.rut || '' }}<template v-if="detail.head_teacher"> · Profesor/a jefe: {{ detail.head_teacher }}</template></p></div><div class="drawer-head-actions"><button v-if="capabilities.can_export && !detailLoading" type="button" title="Ficha individual PDF" @click="exportStudent('individual')"><i class="bx bxs-file-pdf"></i></button><button v-if="capabilities.can_export && !detailLoading" type="button" title="PDF para entrevista familiar" @click="exportStudent('family_interview')"><i class="bx bx-group"></i></button><button type="button" aria-label="Cerrar" @click="closeDetail"><i class="bx bx-x"></i></button></div></header>
        <div v-if="detailLoading" class="drawer-loading"><span class="spinner-border"></span>Reconstruyendo historial válido…</div>
        <template v-else>
          <div class="student-summary"><div><span>Asistencia</span><strong>{{ pct(detail.summary?.attendance_percentage) }}</strong></div><div><span>Días perdidos</span><strong>{{ detail.summary?.days_absent || 0 }}</strong></div><div><span>Sin justificar</span><strong>{{ detail.summary?.unjustified_absences || 0 }}</strong></div><div><span>Racha actual</span><strong>{{ detail.summary?.consecutive_absences || 0 }}</strong></div><AttendanceRiskBadge :level="detail.risk?.level" :label="detail.risk?.label" /></div>
          <div class="explain"><i class="bx bx-bulb"></i><div><strong>Por qué se prioriza</strong><p v-for="reason in detail.risk?.explanations || ['Sin señales suficientes para priorización.']" :key="reason">{{ reason }}</p></div></div>
          <section class="drawer-section"><div class="section-heading"><div><span>HISTORIAL</span><h3>Calendario de asistencia registrada</h3></div><small>Sin registro no se considera ausencia</small></div><div class="calendar"><span v-for="day in (detail.calendar || []).slice(-90)" :key="day.date" :class="[day.status, { justified: day.is_justified, late: day.minutes_late>0, early: day.early_departure }]" :title="`${date(day.date)} · ${day.status}${day.is_justified?' justificada':''}`">{{ new Date(`${day.date}T12:00:00`).getDate() }}</span><p v-if="!(detail.calendar || []).length">Sin registros oficiales en el periodo.</p></div><div class="legend"><span><i class="present"></i>Presente</span><span><i class="absent"></i>Ausente</span><span><i class="justified"></i>Justificada</span><span><i class="late"></i>Atraso/retiro</span></div></section>
          <section class="drawer-section"><div class="section-heading"><div><span>PATRONES</span><h3>Señales activas</h3></div></div><div class="pattern-list"><article v-for="pattern in detail.patterns || []" :key="pattern.id"><span class="pattern-icon"><i class="bx bx-pulse"></i></span><div><strong>{{ pattern.description }}</strong><p>{{ pattern.occurrence_count }} ocurrencias · {{ pct(pattern.confidence_score) }} confianza · {{ pattern.confidence_label }}</p></div></article><p v-if="!(detail.patterns || []).length" class="muted">Sin patrones estadísticamente suficientes.</p></div></section>
          <section class="drawer-section"><div class="section-heading"><div><span>EXPEDIENTES</span><h3>Gestión y acompañamiento</h3></div><button v-if="capabilities.can_manage_cases" type="button" class="btn btn-primary btn-sm" @click="creating=!creating"><i class="bx bx-folder-plus"></i>Nuevo expediente</button></div><form v-if="creating" class="case-form" @submit.prevent="createCase"><label><span>Situación inicial</span><textarea v-model="caseForm.initial_situation" required rows="3"></textarea></label><div class="form-grid"><label><span>Prioridad</span><select v-model="caseForm.priority"><option value="preventive">Preventiva</option><option value="medium">Media</option><option value="high">Alta</option><option value="critical">Crítica</option></select></label><label><span>Responsable</span><select v-model="caseForm.responsible_user_id"><option value="">Por asignar</option><option v-for="user in configuration.assignable_users || []" :key="user.id" :value="user.id">{{ user.name }}</option></select></label><label><span>Adulto referente</span><select v-model="caseForm.reference_adult_user_id"><option value="">Sin asignar</option><option v-for="user in configuration.assignable_users || []" :key="user.id" :value="user.id">{{ user.name }}</option></select></label><label><span>Próxima revisión</span><input v-model="caseForm.next_review_on" type="date"></label></div><label><span>Fundamento trazable</span><input v-model="caseForm.reason" required></label><div class="form-actions"><button type="button" class="btn btn-light" @click="creating=false">Cancelar</button><button type="submit" class="btn btn-primary"><i class="bx bx-save"></i>Crear expediente</button></div></form><div class="case-list"><article v-for="item in detail.cases || []" :key="item.id"><div><strong>{{ item.folio }}</strong><span>{{ item.status.replaceAll('_',' ') }} · {{ date(item.opened_at) }}</span></div><span class="case-priority">{{ item.priority }}</span></article><p v-if="!(detail.cases || []).length" class="muted">Aún no hay expedientes abiertos para este año.</p></div></section>
        </template>
      </aside>
    </div>
  </section>
</template>

<style scoped>
.students-workspace{display:grid;gap:.8rem}.filter-bar{display:grid;grid-template-columns:minmax(220px,1fr) repeat(3,minmax(150px,.55fr)) auto;align-items:end;gap:.6rem;border:1px solid #e1e7ee;border-radius:11px;background:#fff;padding:.8rem}.filter-bar label span{display:block;margin-bottom:.25rem;color:#69768a;font-size:.61rem;font-weight:700}.filter-bar input,.filter-bar select,.case-form input,.case-form select,.case-form textarea{width:100%;min-height:37px;border:1px solid #dce2e9;border-radius:7px;background:#fff;padding:.45rem .6rem;color:#2f3b4d;font-size:.69rem}.search{position:relative}.search i{position:absolute;left:.65rem;bottom:.62rem;color:#8a95a5}.search input{padding-left:2rem}.filter-bar .btn{display:flex;align-items:center;gap:.25rem;min-height:37px;font-size:.68rem}.table-panel{overflow:hidden;border:1px solid #e1e7ee;border-radius:11px;background:#fff}.table{font-size:.68rem}.table thead th{border-bottom:1px solid #dfe5ec;background:#f7f8fa;color:#687589;font-size:.6rem;font-weight:750;letter-spacing:.025em;white-space:nowrap}.table thead button{border:0;background:transparent;color:inherit;font:inherit;padding:0}.table td{border-color:#eef1f4;color:#384457}.student-link{display:block;max-width:220px;border:0;background:transparent;padding:0;text-align:left}.student-link strong,.student-link span,.course-name,.muted,.trend,.signal{display:block}.student-link strong{overflow:hidden;color:#314364;font-size:.7rem;text-overflow:ellipsis;white-space:nowrap}.student-link span,.muted{color:#8792a1;font-size:.59rem}.danger{color:#c13c4a}.trend{margin-top:.12rem;font-size:.58rem}.trend.improving{color:#238264}.trend.declining{color:#c13c4a}.signal{width:max-content;color:#64748b;font-size:.58rem}.signal.critical{margin-top:.14rem;color:#c13c4a;font-weight:700}.open-button{display:grid;place-items:center;width:30px;height:30px;border:1px solid #dfe4eb;border-radius:7px;background:#fff;color:#405189}.state{display:flex;align-items:center;justify-content:c