-bottom:.7rem;border:1px solid #d9e1ee;border-radius:9px;background:#f8faff;padding:.7rem}.case-form label span{display:block;margin-bottom:.22rem;color:#657187;font-size:.59rem;font-weight:700}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.5rem}.form-actions{display:flex;justify-content:flex-end;gap:.4rem}.form-actions .btn{display:flex;align-items:center;gap:.25rem;font-size:.64rem}.case-list{display:grid;gap:.35rem}.case-list article{display:flex;align-items:center;justify-content:space-between;border:1px solid #e7ebf0;border-radius:7px;padding:.55rem}.case-list strong,.case-list span{display:block}.case-list strong{color:#344157;font-size:.67rem}.case-list span{color:#7d899a;font-size:.57rem;text-transform:capitalize}.case-priority{border-radius:999px;background:#f3f4f7;padding:.24rem .45rem!important}@media(max-width:1100px){.filter-bar{grid-template-columns:repeat(2,1fr)}.filter-bar .search{grid-column:1/-1}.student-summary{grid-template-columns:repeat(2,1fr)}.calendar{grid-template-columns:repeat(10,1fr)}}@media(max-width:600px){.filter-bar{grid-template-columns:1fr}.student-summary{grid-template-columns:1fr 1fr}.form-grid{grid-template-columns:1fr}.calendar{grid-template-columns:repeat(7,1fr)}}
.drawer-head-actions{display:flex;gap:.35rem}.drawer-head-actions button:hover{background:#e5e9f2;color:#405189}
